import { ScrubNumber } from './ScrubNumber'
import { customColorName, deriveThemeColorRoles } from './themeColorDerivation'
import { writeStoredThemes } from './themeStorage'
import { fieldGroupLabelClass } from './variants/kit'

type PaletteMode = 'light' | 'dark'

/** The 14 `TLDefaultColor` roles, grouped and ordered the way the brief asks
 *  for — Fill, Frame, Note, Highlight. */
const ROLE_GROUPS: Array<{ label: string; roles: Array<keyof TLDefaultColor> }> = [
	{ label: 'Fill', roles: ['solid', 'semi', 'pattern', 'fill', 'linedFill'] },
	{ label: 'Frame', roles: ['frameHeadingStroke', 'frameHeadingFill', 'frameStroke', 'frameFill', 'frameText'] },
	{ label: 'Note', roles: ['noteFill', 'noteText'] },
	{ label: 'Highlight', roles: ['highlightSrgb', 'highlightP3'] },
]

const ROLE_LABELS: Partial<Record<keyof TLDefaultColor, string>> = {
	solid: 'Solid', semi: 'Semi', pattern: 'Pattern', fill: 'Fill', linedFill: 'Lined fill',
	frameHeadingStroke: 'Heading stroke', frameHeadingFill: 'Heading fill',
	frameStroke: 'Stroke', frameFill: 'Fill', frameText: 'Heading text',
	noteFill: 'Fill', noteText: 'Text',
	highlightSrgb: 'sRGB', highlightP3: 'Display P3',
}

/** A named colour's own 14 roles, i.e. the `TLThemeDefaultColors` keys whose
 *  value is a `TLDefaultColor` object rather than a plain UI-colour string
 *  (`text`, `background`, `selectionStroke`, …). */
function namedColorKeys(colors: Record<string, unknown>): string[] {
	return Object.keys(colors).filter((key) => {
		const value = colors[key]
		return typeof value === 'object' && value !== null && 'solid' in (value as object)
	})
}

/** The same swatch+popover+hex-input control `Inspector.tsx`'s `ColorRow`
 *  draws, minus the `InspectorControl`-specific mixed/unset/clear states a
 *  theme role never has (it always holds a real colour). Kept as its own
 *  small component rather than generalizing `ColorRow` itself: the two
 *  surfaces read genuinely different shapes (a shared selection's paint vs.
 *  one theme's own record), and forcing them through one prop contract would
 *  have cost more than the ~30 lines this duplicates. */
function ThemeColorField({
	label,
	testId,
	value,
	onChange,
}: {
	label: string
	testId: string
	value: string
	onChange(next: string): void
}) {
	const [draft, setDraft] = useState<string | null>(null)
	const hex = /^#[0-9a-f]{6,8}$/i.test(value) ? value : '#000000ff'
	const commitText = () => {
		if (draft === null) return
		const next = draft.trim()
		setDraft(null)
		if (next === '' || !isColor(next) || next === value) return
		onChange(next)
	}
	return (
		<div className="flex items-center gap-1.5">
			<span className="w-28 shrink-0 truncate text-xs text-muted-foreground" title={label}>{label}</span>
			<Popover>
				<PopoverTrigger
					render={
						<button
							type="button"
							aria-label={`${label} picker`}
							data-testid={`theme-color-${testId}`}
							className="size-6 shrink-0 rounded-md border border-border"
							style={{ background: value }}
						/>
					}
				/>
				<PopoverContent className="w-auto p-2">
					<HexAlphaColorPicker color={hex} onChange={onChange} />
				</PopoverContent>
			</Popover>
			<Input
				spellCheck={false}
				value={draft ?? value}
				aria-label={`${label} value`}
				data-testid={`theme-color-text-${testId}`}
				className="h-7 flex-1"
				onChange={(event) => setDraft(event.target.value)}
				onBlur={commitText}
				onKeyDown={(event) => {
					if (event.key === 'Enter') commitText()
					if (event.key === 'Escape') setDraft(null)
				}}
			/>
		</div>
	)
}

/** One named colour's collapsible: its own light/dark toggle, a 14-swatch
 *  preview strip, and a colour row per role, grouped Fill/Frame/Note/Highlight. */
function NamedColorSection({
	name,
	theme,
	defaultMode,
	onEditRole,
}: {
	name: string
	theme: TLTheme
	defaultMode: PaletteMode
	onEditRole(mode: PaletteMode, role: keyof TLDefaultColor, value: string): void
}) {
	const [mode, setMode] = useState<PaletteMode>(defaultMode)
	const palette = theme.colors[mode][name as keyof typeof theme.colors.light] as unknown as TLDefaultColor | undefined
	if (!palette) return null
	return (
		<Collapsible>
			<CollapsibleTrigger
				render={
					<button
						type="button"
						data-testid={`theme-color-group-${name}`}
						className="group flex w-full appearance-none items-center justify-between gap-2 border-0 bg-transparent px-3 py-2 text-xs font-semibold text-foreground outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
					/>
				}
			>
				<span className="flex min-w-0 items-center gap-2">
					<span className="size-4 shrink-0 rounded-full border border-border" style={{ background: palette.solid }} />
					<span className="truncate">{name}</span>
				</span>
				<ChevronRight
					aria-hidden="true"
					className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-150 group-data-[panel-open]:rotate-90"
				/>
			</CollapsibleTrigger>
			<CollapsibleContent className="flex flex-col gap-2 px-3 pb-3">
				<ToggleGroup
					value={[mode]}
					onValueChange={(next) => { if (next[0]) setMode(next[0] as PaletteMode) }}
					aria-label={`${name} palette`}
					className="w-full"
				>
					<ToggleGroupItem value="light" data-testid={`theme-mode-${name}-light`} className="flex-1 text-xs">Light</ToggleGroupItem>
					<ToggleGroupItem value="dark" data-testid={`theme-mode-${name}-dark`} className="flex-1 text-xs">Dark</ToggleGroupItem>
				</ToggleGroup>
				<div className="flex flex-wrap gap-1" data-testid={`theme-swatch-strip-${name}`}>
					{Object.entries(palette).map(([role, value]) => (
						<span
							key={role}
							title={`${role}: ${value}`}
							className="size-4 rounded-sm border border-border"
							style={{ background: value }}
						/>
					))}
				</div>
				{ROLE_GROUPS.map((group) => (
					<div key={group.label} className="flex flex-col gap-0">
						<p className={fieldGroupLabelClass}>{group.label}</p>
						<div className="flex flex-col gap-1.5">
							{group.roles.map((role) => (
								<ThemeColorField
									key={role}
									label={ROLE_LABELS[role] ?? role}
									testId={`${name}-${mode}-${role}`}
									value={palette[role]}
									onChange={(value) => onEditRole(mode, role, value)}
								/>
							))}
						</div>
					</div>
				))}
			</CollapsibleContent>
		</Collapsible>
	)
}

/** The reactive adapter — nothing above this line reads the editor. */
export function ThemePanel({ editor }: { editor: Editor }) {
	const theme = useValue('tldraw styling lab theme', () => editor.getCurrentTheme(), [editor])
	const liveMode = useValue('tldraw styling lab theme colour mode', () => editor.getColorMode(), [editor])
	const [addHex, setAddHex] = useState('#3366ff')

	const colorNames = useMemo(() => namedColorKeys(theme.colors.light), [theme])

	/** Every edit goes through this one path: patch the live theme, re-run the
	 *  registration tldraw's own `<Tldraw themes>` prop would otherwise run on
	 *  the NEXT mount (see the file header), and persist the result. */
	const patchTheme = (patch: (next: TLTheme) => TLTheme) => {
		let patched: TLTheme | undefined
		editor.updateThemes((themes) => {
			patched = patch(themes.default)
			return { ...themes, default: patched }
		})
		const themes = editor.getThemes()
		registerColorsFromThemes(themes)
		writeStoredThemes(themes)
	}

	const setScalar = (key: 'fontSize' | 'lineHeight' | 'strokeWidth', value: number) => {
		patchTheme((next) => ({ ...next, [key]: value }))
	}

	const editRole = (name: string, mode: PaletteMode, role: keyof TLDefaultColor, value: string) => {
		patchTheme((next) => ({
			...next,
			colors: {
				...next.colors,
				[mode]: {
					...next.colors[mode],
					[name]: { ...(next.colors[mode] as unknown as Record<string, TLDefaultColor>)[name], [role]: value },
				},
			},
		}))
	}

	const resetToDefaults = () => {
		editor.updateThemes(() => resolveThemes())
		const themes = editor.getThemes()
		registerColorsFromThemes(themes)
		writeStoredThemes(themes)
	}

	const addColor = () => {
		if (!isColor(addHex) || !/^#[0-9a-f]{6}$/i.test(addHex)) return
		const name = customColorName(addHex)
		patchTheme((next) => ({
			...next,
			colors: {
				light: { ...next.colors.light, [name]: deriveThemeColorRoles(addHex, 'light') },
				dark: { ...next.colors.dark, [name]: deriveThemeColorRoles(addHex, 'dark') },
			},
		}))
	}

	return (
		<div data-testid="theme-panel" className="flex h-full flex-col">
			<header className="flex flex-col gap-1 border-b border-border px-3 py-2.5">
				<div className="flex items-center justify-between gap-2">
					<h2 className="text-sm font-semibold text-foreground">Theme</h2>
					<Button size="xs" variant="ghost" data-testid="theme-reset" onClick={resetToDefaults}>
						Reset to tldraw defaults
					</Button>
				</div>
				{/* WHY this hint is here and not just in a code comment: `updateThemes`
				    writes to a plain Atom the record store's UndoManager never walks
				    (ThemeManager.ts), so Ctrl+Z after a theme edit undoes the LAST
				    document change instead — a person needs to see that before they
				    lean on undo and lose nothing, or reach for undo and get confused
				    when a shape edit reverts instead. */}
				<p className="text-[11px] text-muted-foreground">
					Theme edits are not undo-tracked — they are app settings, not part of the document. Use Reset to go back.
				</p>
			</header>
			<ScrollArea className="min-h-0 flex-1">
				<div className="flex flex-col gap-0 px-3 py-3">
					<p className={fieldGroupLabelClass}>Scale</p>
					<div className="grid grid-cols-3 gap-1.5">
						<ScrubNumber
							value={theme.fontSize} min={4} max={64} step={1} unit="px" glyph="type"
							label="Font size" testId="theme-fontSize" title="Base font size — every shape's font size is a multiple of this."
							onChange={(value) => setScalar('fontSize', value)}
						/>
						<ScrubNumber
							value={theme.lineHeight} min={0.8} max={3} step={0.05} glyph="lineHeight"
							label="Line height" testId="theme-lineHeight" title="Base line-height multiplier."
							onChange={(value) => setScalar('lineHeight', value)}
						/>
						<ScrubNumber
							value={theme.strokeWidth} min={0.25} max={24} step={0.25} unit="px" glyph="weight"
							label="Stroke width" testId="theme-strokeWidth" title="Base outline width — every shape's stroke width is a multiple of this."
							onChange={(value) => setScalar('strokeWidth', value)}
						/>
					</div>
				</div>
				<Separator />
				<div className="flex flex-col">
					{colorNames.map((name) => (
						<NamedColorSection
							key={name}
							name={name}
							theme={theme}
							defaultMode={liveMode}
							onEditRole={(mode, role, value) => editRole(name, mode, role, value)}
						/>
					))}
				</div>
				<Separator />
				<Field className="gap-2 p-3">
					<FieldDescription>
						Add colour — one hex, both palettes, 14 roles derived (see themeColorDerivation.ts).
					</FieldDescription>
					<div className="flex items-center gap-1.5">
						<span
							className="size-6 shrink-0 rounded-md border border-border"
							style={{ background: /^#[0-9a-f]{6}$/i.test(addHex) ? addHex : 'transparent' }}
						/>
						<Input
							spellCheck={false}
							value={addHex}
							placeholder="#3366ff"
							aria-label="New colour hex"
							data-testid="theme-add-hex"
							className="h-7 flex-1"
							onChange={(event) => setAddHex(event.target.value)}
						/>
						<Button size="xs" variant="outline" data-testid="theme-add-color" onClick={addColor}>
							Add
						</Button>
					</div>
				</Field>
			</ScrollArea>
		</div>
	)
}

/**
 * The census's own oracle: parse the `*ShapeUtilDisplayValues` interfaces
 * straight out of `node_modules/tldraw` at test time, rather than trusting
 * `displayValueCensus.ts`'s hand-written key lists. A tldraw bump that adds,
 * renames or removes a display value shows up here as a mismatch between the
 * parsed keys and `REACHED ∪ DOCUMENTED`, before it ever reaches a person
 * clicking around the panel.
 */
// WHY a file-scoped reference rather than adding "node" to tsconfig.app.json's
// `types`: that array is what keeps the browser app project honest about
// having no Node globals in scope — this is the one file in `src/` that
// genuinely runs under Node (vitest) and reads the filesystem, so it gets its
// own ambient types instead of widening every other file's.
/// <reference types="node" />
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'

import {
	DISPLAY_VALUE_SOURCES,
	DOCUMENTED,
	REACHED,
	type DisplayValueShapeKind,
} from './displayValueCensus'

const here = dirname(fileURLToPath(import.meta.url))
const tldrawShapesRoot = join(here, '..', '..', 'node_modules', 'tldraw', 'src', 'lib', 'shapes')

/**
 * Pull the members of one `export interface Name { ... }` (or tldraw's one
 * `export type Name = object` alias, treated as zero members) out of a source
 * file's text.
 *
 * WHY a regex and not the TypeScript compiler API: every interface here is a
 * single, non-nested `{ key: type }` block — no inline object types, no
 * generics — so a line-scoped pattern is the whole grammar this needs, the
 * same trade this repo's `docs/build_font_size_type_role.py` donor precedent
 * (named in the module header) makes against tldraw's own source.
 */
function parseInterfaceKeys(source: string, interfaceName: string): string[] {
	const aliasToObject = new RegExp(`\\btype\\s+${interfaceName}\\s*=\\s*object\\b`)
	if (aliasToObject.test(source)) return []

	const header = new RegExp(`\\binterface\\s+${interfaceName}\\b[^{]*\\{`)
	const headerMatch = header.exec(source)
	if (!headerMatch) {
		throw new Error(`could not find "interface ${interfaceName}" in the given source`)
	}
	// WHY a brace-depth scan and not a `{([\s\S]*?)\n}` regex: `{}` on one
	// line (image/video's empty interfaces) has no `\n` before its close, so a
	// non-greedy regex skips straight past it to the NEXT `\n}` in the file —
	// which belongs to a wholly unrelated interface further down. Counting
	// braces from the interface's own `{` is the only thing that finds ITS
	// close reliably, empty or not.
	const bodyStart = headerMatch.index + headerMatch[0].length
	let depth = 1
	let index = bodyStart
	while (depth > 0) {
		if (index >= source.length) {
			throw new Error(`unbalanced braces reading "interface ${interfaceName}"`)
		}
		if (source[index] === '{') depth += 1
		else if (source[index] === '}') depth -= 1
		index += 1
	}
	const body = source.slice(bodyStart, index - 1)
	const keys: string[] = []
	for (const line of body.split('\n')) {
		const field = /^\s*(\w+)\s*:/.exec(line)
		if (field) keys.push(field[1])
	}
	return keys
}

function readLiveKeys(kind: DisplayValueShapeKind): string[] {
	const { file, interfaceName } = DISPLAY_VALUE_SOURCES[kind]
	const source = readFileSync(join(tldrawShapesRoot, file), 'utf8')
	return parseInterfaceKeys(source, interfaceName)
}

describe('display value census', () => {
	const kinds = Object.keys(DISPLAY_VALUE_SOURCES) as DisplayValueShapeKind[]

	for (const kind of kinds) {
		it(`${kind}: every live display-value key is reached or documented`, () => {
			const liveKeys = readLiveKeys(kind)
			const reached = REACHED[kind]
			const documented = DOCUMENTED[kind]

			const missing = liveKeys.filter((key) => !reached.has(key) && !(key in documented))
			expect(missing, `${kind} has undeclared keys: ${missing.join(', ')}`).toEqual([])

			// The other direction: a key this file claims for a shape that no
			// longer declares it (a tldraw removal) is exactly as stale as a
			// missing one, and would otherwise rot silently.
			const liveSet = new Set(liveKeys)
			const stale = [...reached, ...Object.keys(documented)].filter((key) => !liveSet.has(key))
			expect(stale, `${kind} claims keys tldraw no longer declares: ${stale.join(', ')}`).toEqual([])
		})
	}

	it('prints the totals — reached / documented / total, re-measured against the pinned tldraw', () => {
		let reachedTotal = 0
		let documentedTotal = 0
		let liveTotal = 0
		for (const kind of kinds) {
			liveTotal += readLiveKeys(kind).length
			reachedTotal += REACHED[kind].size
			documentedTotal += Object.keys(DOCUMENTED[kind]).length
		}
		console.log(`[display value census] reached ${reachedTotal} / documented ${documentedTotal} / total ${liveTotal} (tldraw@5.3.2)`)
		expect(reachedTotal + documentedTotal).toBe(liveTotal)
		// A floor, not a target: the number itself is provenance (see
		// displayValueCensus.ts's module header), but a census that quietly
		// dropped to single digits would mean the parser broke, not that
		// tldraw shrank.
		expect(liveTotal).toBeGreaterThan(40)
	})
})

import { describe, expect, it } from 'vitest'

import { customColorName, deriveThemeColorRoles, mixHex } from './themeColorDerivation'

describe('mixHex', () => {
	it('returns the input unchanged at ratio 0', () => {
		expect(mixHex('#3366ff', 'white', 0)).toBe('#3366ff')
		expect(mixHex('#3366ff', 'black', 0)).toBe('#3366ff')
	})

	it('reaches pure white/black at ratio 1', () => {
		expect(mixHex('#3366ff', 'white', 1)).toBe('#ffffff')
		expect(mixHex('#3366ff', 'black', 1)).toBe('#000000')
	})

	it('lightens every channel monotonically toward white as the ratio grows', () => {
		const low = mixHex('#204080', 'white', 0.2)
		const high = mixHex('#204080', 'white', 0.8)
		const channel = (hex: string, index: number) => Number.parseInt(hex.slice(1 + index * 2, 3 + index * 2), 16)
		for (let index = 0; index < 3; index += 1) {
			expect(channel(high, index)).toBeGreaterThanOrEqual(channel(low, index))
		}
	})
})

describe('customColorName', () => {
	it('normalizes case and drops the leading #', () => {
		expect(customColorName('#AABBCC')).toBe('custom-aabbcc')
		expect(customColorName('aabbcc')).toBe('custom-aabbcc')
	})
})

describe('deriveThemeColorRoles', () => {
	it('carries all 14 TLDefaultColor roles', () => {
		const roles = deriveThemeColorRoles('#3366ff', 'light')
		expect(Object.keys(roles).sort()).toEqual([
			'fill', 'frameFill', 'frameHeadingFill', 'frameHeadingStroke', 'frameStroke',
			'frameText', 'highlightP3', 'highlightSrgb', 'linedFill', 'noteFill', 'noteText',
			'pattern', 'semi', 'solid',
		])
	})

	it('keeps solid and fill as the exact picked hex, in both modes', () => {
		const light = deriveThemeColorRoles('#3366ff', 'light')
		const dark = deriveThemeColorRoles('#3366ff', 'dark')
		expect(light.solid).toBe('#3366ff')
		expect(light.fill).toBe('#3366ff')
		expect(dark.solid).toBe('#3366ff')
		expect(dark.fill).toBe('#3366ff')
	})

	it('washes light-mode roles toward white and dark-mode roles toward black', () => {
		const light = deriveThemeColorRoles('#204080', 'light')
		const dark = deriveThemeColorRoles('#204080', 'dark')
		// light's frameFill is a pale tint (every channel rises toward 255);
		// dark's is a dim shade (every channel falls toward 0).
		expect(light.frameFill.toLowerCase() > '#204080').toBe(true)
		expect(dark.frameFill.toLowerCase() < '#204080').toBe(true)
	})

	it('mixes the two text-on-a-wash roles the opposite way, for contrast', () => {
		const light = deriveThemeColorRoles('#204080', 'light')
		// light mode washes toward white; its text role should darken instead.
		expect(light.frameText.toLowerCase() < '#204080').toBe(true)
		expect(light.noteText.toLowerCase() < '#204080').toBe(true)
	})
})

/**
 * "Add colour" needs all 14 `TLDefaultColor` roles from one picked hex, for
 * both the light and the dark palette — tldraw's own designers hand-tuned
 * the stock thirteen, and this app has no equivalent design pass to run per
 * custom colour. The formula below is deliberately simple and documented
 * rather than an attempt to reverse-engineer tldraw's actual palette math:
 * `solid`/`fill` are the picked hex itself, every wash-like role
 * (`semi`/`pattern`/`linedFill`/the frame and note fills) is a mix toward
 * white (light mode) or black (dark mode) at a fixed ratio per role, and the
 * two text-on-a-wash roles (`frameText`/`noteText`) mix the OTHER way for
 * contrast. `highlightSrgb`/`highlightP3` are the raw hex — this app has no
 * P3-gamut conversion available, so both roles get the same sRGB value; a
 * real P3 palette would diverge slightly on a wide-gamut display.
 */
import type { TLDefaultColor } from 'tldraw'

function clampChannel(value: number): number {
	return Math.min(255, Math.max(0, Math.round(value)))
}

function parseHex6(hex: string): [number, number, number] {
	const normalized = hex.trim().toLowerCase()
	const match = /^#?([0-9a-f]{6})$/.exec(normalized)
	if (!match) throw new Error(`not a 6-digit hex colour: ${hex}`)
	const value = match[1]
	return [
		Number.parseInt(value.slice(0, 2), 16),
		Number.parseInt(value.slice(2, 4), 16),
		Number.parseInt(value.slice(4, 6), 16),
	]
}

function toHex6([r, g, b]: [number, number, number]): string {
	return `#${[r, g, b].map((channel) => clampChannel(channel).toString(16).padStart(2, '0')).join('')}`
}

/** Linear-interpolate `hex` toward white (`toward: 'white'`) or black
 *  (`toward: 'black'`) by `ratio` (0 = `hex` unchanged, 1 = pure white/black). */
export function mixHex(hex: string, toward: 'white' | 'black', ratio: number): string {
	const [r, g, b] = parseHex6(hex)
	const target = toward === 'white' ? 255 : 0
	const t = Math.min(1, Math.max(0, ratio))
	return toHex6([
		r + (target - r) * t,
		g + (target - g) * t,
		b + (target - b) * t,
	])
}

/** `custom-<hex>`, the name `derivePaletteEntry`'s caller registers both
 *  palettes under — matches this file's own hex validation, so a name built
 *  from it is always well-formed. */
export function customColorName(hex: string): string {
	const [r, g, b] = parseHex6(hex)
	return `custom-${toHex6([r, g, b]).slice(1)}`
}

/**
 * All 14 `TLDefaultColor` roles for one hex, in one palette's direction.
 *
 * `light` washes toward white and darkens its two text roles toward black;
 * `dark` does the reverse, matching the shape of tldraw's own light/dark
 * palettes (a light-mode fill is a pale tint, a dark-mode fill is a dim
 * shade) without claiming to reproduce their exact numbers.
 */
export function deriveThemeColorRoles(hex: string, mode: 'light' | 'dark'): TLDefaultColor {
	const wash = mode === 'light' ? 'white' : 'black'
	const ink = mode === 'light' ? 'black' : 'white'
	const mix = (ratio: number) => mixHex(hex, wash, ratio)
	return {
		solid: hex,
		semi: mix(0.82),
		pattern: mix(0.35),
		fill: hex,
		linedFill: mix(0.15),
		frameHeadingStroke: hex,
		frameHeadingFill: mix(0.88),
		frameStroke: hex,
		frameFill: mix(0.92),
		frameText: mixHex(hex, ink, 0.35),
		noteFill: mix(0.55),
		noteText: mixHex(hex, ink, 0.55),
		highlightSrgb: hex,
		highlightP3: hex,
	}
}

/**
 * Where the Theme tab's edits live between sessions.
 *
 * WHY `localStorage`, not the document: `editor.updateThemes` is deliberately
 * NOT tracked by tldraw's own undo stack (see `ThemeManager.ts` — it lives on
 * a plain `Atom`, never in the record store `UndoManager` walks), because a
 * theme is app-global state, not a property of any one shape or document.
 * Persisting it the same way `persistenceKey` persists the board would put
 * app state inside document state — the same category error `persistenceKey`
 * itself is skipped for on a seeded/test load (see `board/mount.tsx`), and
 * for the identical reason: a `?seed=` run must never read, or write,
 * whatever a person left in their own browser.
 */
import type { TLThemes } from 'tldraw'

const STORAGE_KEY = 'tldraw_styling_lab.themes'

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null
}

/** `undefined` on a private window, a first run, or corrupt JSON — every
 *  caller already treats "no themes" as "use tldraw's own defaults". */
export function readStoredThemes(): Partial<TLThemes> | undefined {
	try {
		const raw = window.localStorage.getItem(STORAGE_KEY)
		if (!raw) return undefined
		const parsed: unknown = JSON.parse(raw)
		return isRecord(parsed) ? (parsed as Partial<TLThemes>) : undefined
	} catch {
		return undefined
	}
}

export function writeStoredThemes(themes: TLThemes): void {
	try {
		window.localStorage.setItem(STORAGE_KEY, JSON.stringify(themes))
	} catch {
		// A full quota or a private window must not break editing the theme —
		// the edit still applies live, it just will not survive a reload.
	}
}

export function clearStoredThemes(): void {
	try {
		window.localStorage.removeItem(STORAGE_KEY)
	} catch {
		// See writeStoredThemes.
	}
}

/**
 * The three variants share one skeleton (`kit.tsx`) and one behaviour
 * contract (whole-field scrub, resizable dock — both mandatory, both live
 * in `ScrubNumber.tsx`/`Inspector.tsx` regardless of variant). What actually
 * differs is a THEME plus a few layout decisions, gathered here so
 * `Inspector.tsx`/`ThemePanel.tsx` branch on one small table instead of
 * three forked files.
 *
 * The palette itself is NOT here — it lives in `src/styles/app.css`'s
 * `[data-variant]` blocks, because it has to reach both the dock (a normal
 * descendant) and re-point tokens (`--background`, `--foreground`, …) the
 * existing shadcn-flavoured markup in Inspector.tsx/ThemePanel.tsx already
 * reads — see that file's own WHY. `data-variant` on the dock root
 * (`[data-testid="inspector"]`) is the only wire between the two: this
 * module decides WHICH number, CSS decides what it looks like.
 */
import { GEO_GLYPHS } from '../glyphs'

// Round 2 (Zach's verdict on round 1: "very similar… aim for Figma's
// compactness, measured in LINE COUNT per section"): 4/5/6 join 1/2/3 in the
// same `VariantId`/`VARIANTS` table rather than a parallel one, so the dock
// picker, the gallery and every journey keep branching on one number. 4/5/6
// render through a completely different component tree
// (`variants/figmaVariants.tsx`, keyed on the Figma anatomy Zach specified
// element-by-element) — `inlinePrefixes`/`iconControlIds`/`selectThreshold`
// below are round 1's own rendering knobs and stay meaningless for 4/5/6,
// kept at inert defaults only so `VariantTheme` stays one shared shape for
// the picker/gallery's name+tagline+round fields.
export type VariantId = 1 | 2 | 3 | 4 | 5 | 6 | 7

export interface VariantTheme {
	id: VariantId
	key: string
	name: string
	/** One line, printed in the gallery and nowhere else — not UI copy. */
	tagline: string
	/** Which babble round this variant belongs to — what splits the dock
	 *  picker into "1 2 3 · 4 5 6 · 7" (`VariantPicker`, kit.tsx). Round 3
	 *  has exactly one member on purpose (see `isFigmaExactVariant`). */
	round: 1 | 2 | 3
	/** Caption-above-field (V1/V2) vs. letter-prefix-inside-field (V3) for the
	 *  geometry scalars a prefix reads naturally on (x/y/w/h/rotation/opacity).
	 *  Round-2 variants (4/5/6) never read this — see the module comment. */
	inlinePrefixes: boolean
	/** Which `FieldSpec` ids draw their options from `TLDRAW_ICONS`
	 *  (`tldrawIcons.tsx`) instead of a text label. `'all'` is V2's own
	 *  brief verbatim — "every enum tldraw itself draws an icon for" — every
	 *  other variant names the open-pencil split by hand (icons for
	 *  alignment, words for fill/dash/size/font). An id absent from
	 *  `TLDRAW_ICONS` (`geo` — the app's own rounded-rect has no tldraw
	 *  asset, see that file's WHY) always falls back to the hand-drawn
	 *  `GEO_GLYPHS`/`ARROWHEAD_PATHS` tiles regardless of this setting. */
	iconControlIds: 'all' | Set<string>
	/** An enum with more than this many options collapses to a Select
	 *  instead of a segmented control. V1/V2 never do this (Infinity); V3's
	 *  brief calls it out by name for font/fill-style/dash. */
	selectThreshold: number
}

