/* -------------------------------------------------------------- grid/group */

export function FieldGroup({ label, children }: { label?: string; children: React.ReactNode }) {
	return (
		<div className="flex flex-col gap-1.5">
			{label ? <span className={fieldGroupLabelClass}>{label}</span> : null}
			{children}
